      "content": "{\n  \"name\": \"dsh-agent-compare\",\n  \"version\": \"1.0.1\",\n  \"description\": \"同一需求，两版真跑：在 DSH 对话里比较、验证并审查采用。A DeepSeek Harness plugin for two implementations, live previews, shared checks and reviewed adoption.\",\n  \"type\": \"module\",\n  \"packageManager\": \"npm@12.2.1\",\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org/\",\n    \"access\": \"public\"\n  },\n  \"main\": \"lib/host/index.js\",\n  \"types\": \"lib/host/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/host/index.d.ts\",\n      \"default\": \"./lib/host/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./core\": {\n      \"types\": \"./lib/core/index.d.ts\",\n      \"default\": \"./lib/core/index.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"examples/vite-react-demo\",\n    \"README*.md\",\n    \"CONTRIBUTING.md\",\n    \"docs\",\n    \"LICENSE\",\n    \"!examples/vite-react-demo/node_modules\",\n    \"!examples/vite-react-demo/dist\",\n    \"CHANGELOG.md\",\n    \"assets\",\n    \"screenshots.json\",\n    \"!docs/media/*.mp4\",\n    \"!docs/media/*.gif\",\n    \"!docs/media/social-preview.png\",\n    \"!assets/readme\",\n    \"!docs/measurements\",\n    \"!docs/media/manifest.json\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.22.2 || ^24.15.0 || >=26.0.0\",\n    \"dsh\": \">=0.2.1-rc.3 <0.3.0-0\"\n  },\n  \"scripts\": {\n    \"build\": \"node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\" && tsc -p tsconfig.json && tsc -p tsconfig.client.json && node scripts/wrap-client.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit && tsc -p tsconfig.client.json --noEmit\",\n    \"check:docs\": \"node scripts/check-docs.mjs\",\n    \"test\": \"npm run build && vitest run\",\n    \"test:coverage\": \"npm run build && vitest run --coverage\",\n    \"test:ui\": \"npm run build && node scripts/test-ui.mjs\",\n    \"test:runtime\": \"npm run build && node scripts/test-runtime.mjs\",\n    \"smoke\": \"npm run build && node scripts/smoke.mjs\",\n    \"prepack\": \"npm run build\",\n    \"check:distribution\": \"node scripts/check-distribution.mjs\",\n    \"check:prebuilt\": \"node scripts/check-prebuilt.mjs\",\n    \"test:fast\": \"npm run build && vitest run --project unit\",\n    \"test:integration\": \"npm run build && vitest run --project integration\",\n    \"check:test-projects\": \"node scripts/check-test-projects.mjs\",\n    \"test:managers\": \"npm run build && node scripts/test-managers.mjs\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"parallel-agents\",\n    \"git-worktree\",\n    \"live-preview\",\n    \"blind-test\",\n    \"code-comparison\",\n    \"vite\",\n    \"react\",\n    \"frontend-tools\",\n    \"ab-testing\",\n    \"workflow\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.1-rc.1\",\n    \"react\": \"^18.3.1 || ^19.3.1\",\n    \"@deepseek-ai/dsh-sandbox\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-win32-process\": \"^0.2.1-rc.3\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": t