      "path": "src/core/file-transfer.ts",
      "content": "import { constants } from 'node:fs'\nimport { createHash, randomBytes } from 'node:crypto'\nimport { chmod, copyFile, link, lstat, mkdir, open, realpath, rename, writeFile } from 'node:fs/promises'\nimport path from 'node:path'\nimport { git } from './git.ts'\n\nexport interface FileTransferRef { readonly id: string; readonly token: string }\nexport interface FileFingerprint {\n  readonly kind: 'missing' | 'file' | 'other'\n  readonly sha256?: string\n  readonly size?: number\n  readonly mode?: number\n  readonly device?: string\n  readonly inode?: string\n  readonly modified?: string\n}\n\ninterface Entry {\n  path: string\n  before: FileFingerprint\n  after: FileFingerprint\n  phase: 'prepared' | 'capturing' | 'captured' | 'publishing' | 'published' | 'undoing' | 'restored'\n}\ninterface Journal {\n  schema: 'agent-compare.file-transfer/v1'\n  repo: string\n  ref: FileTransferRef\n  state: 'prepared' | 'writing' | 'applied' | 'restoring' | 'restored' | 'recovery'\n  entries: Entry[]\n}\nexport interface FileTransfer { readonly root: string; readonly journal: Journal }\n\nconst MAX_BYTES = 128 * 1024 * 1024\nconst MAX_ENTRIES = 10000\nconst JOURNAL_BYTES = 8 * 1024 * 1024\nconst MISSING: FileFingerprint = { kind: 'missing' }\nconst equalPath = (a: string, b: string): boolean => process.platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b\nconst errno = (error: unknown, code: string): boolean => (error as NodeJS.ErrnoException).code === code\nconst slot = (transfer: FileTransfer, kind: 'next' | 'before' | 'undo', index: number): string => path.join(transfer.root, kind, String(index))\n\nexport class FileTransferError extends Error {\n  constructor(message: string, readonly paths: string[] = []) { super(message); this.name = 'FileTransferError' }\n}\n\nexport function newFileTransferRef(): FileTransferRef {\n  return { id: randomBytes(16).toString('hex'), token: randomBytes(16).toString('hex') }\n}\n\nfunction validRef(ref: FileTransferRef): void {\n  if (!ref || !/^[0-9a-f]{32}$/.test(ref.id) || !/^[0-9a-f]{32}$/.test(ref.token)) throw new FileTransferError('文件交接记录的标识无效')\n}\n\nfunction validPath(relative: string): void {\n  const parts = relative.split('/')\n  if (!relative || relative.includes('\\\\') || relative.includes('\\0') || path.posix.isAbsolute(relative)\n    || parts.some(part => !part || part === '.' || part === '..' || part.toLowerCase() === '.git' || part.startsWith('.agent-compare-transfer-'))\n    || (process.platform === 'win32' && parts.some(part => /[<>:\"|?*\\x00-\\x1f]/.test(part) || /[. ]$/.test(part)))) {\n    throw new FileTransferError('这个路径不能直接写回，请另存分支查看', [relative])\n  }\n}\n\nasync function statIfPresent(file: string): Promise<Awaited<ReturnType<typeof lstat>> | undefined> {\n  try { return await lstat(file) } catch (error) { if (errno(error, 'ENOENT')) return undefined; throw error }\n}\n\n/** Hash a stable ordinary file without following a substituted symbolic link. */\nexport async function fileFingerprint(file: string): Promise<FileFingerprint> {\n  const initial = await lstat(file, { bigint: true }).catch(error => { if (errno(error, 'ENOENT')) return undefined; throw error })\n  if (!initial) return MISSING\n  if (!initial.isFile() || initial.isSymbolicLink()) return { kind: 'other' }\n  if (initial.size > BigInt(MAX_BYTES)) throw new FileTransferError('单个文件超过直接写回的保留上限，请另存分支')\n  const handle = await open(file, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0))\n  try {\n    const before = await handle.stat({ bigint: true })\n    if (!before.isFile() || String(before.ino) !== String(initial.ino) || String(before.dev) !== String(initial.dev)) throw new FileTransferError('读取文件时路径发生变化')\n    const hash = createHash('sha256'), buffer = Buffer.allocUnsafe(256 * 1024)\n    let position = 0\n    while (true) {\n      const { bytesRead } = await handle.read(buffer, 0, buffer.length, position)\n      if (!bytesRead) break\n      position += bytesRead\n      if (position > MAX_BYTES) throw new FileTransferError('读取期间文件超过直接写回的保留上限')\n      hash.update(buffer.subarray(0, bytesRead))\n    }\n    const after = await handle.stat({ bigint: true }), current = await lstat(file, { bigint: true })\n    if (before.size !== after.size || before.mtimeNs !== after.mtimeNs || before.ctimeNs !== after.ctimeNs\n      || after.ino !== current.ino || after.dev !== current.dev || after.mtimeNs !== current.mtimeNs) throw new FileTransferError('读取期间文件发生变化，请重新检查后再试')\n    return { kind: 'file', sha256: hash.digest('hex'), size: Number(after.size), mode: Number(after.mode), device: String(after.dev), inode: String(after.ino), modified: String(after.mtimeNs) }\n  } finally { await handle.close() }\n}\n\nexport function sameFile(a: FileFingerprint, b: FileFingerprint, identity = true): boolean {\n  if (a.kind !== b.kind) return false\n  if (a.kind === 'missing') return true\n  if (a.kind !== 'file') return false\n  return a.sha256 === b.sha256 && a.size === b.size && a.mode === b.mode\n    && (!identity || (a.device === b.device && a.inode === b.inode))\n}\n\nexport async function transferPreimages(repo: string, paths: readonly string[]): Promise<Record<string, FileFingerprint>> {\n  const result: Record<string, FileFingerprint> = Object.create(null) as Record<string, FileFingerprint>\n  for (const relative of paths) { validPath(relative); result[relative] = await fileFingerprint(path.join(repo, relative)) }\n  return result\n}\n\nasync function ordinaryParents(repo: string, relative: string, create: boolean): Promise<void> {\n  validPath(relative)\n  let current = repo\n  for (const part of relative.split('/').slice(0, -1)) {\n    current = path.join(current, part)\n    if (create) await mkdir(current).catch(error => { if (!errno(error, 'EEXIST')) throw error })\n    const stat = await statIfPresent(current)\n    if (!stat && !create) return\n    if (!stat?.isDirectory() || stat.isSymbolicLink()) throw new FileTransferError('目标的父路径不是普通目录，请另存分支查看', [relative])\n    if (!equalPath(await realpath(current), current)) throw new FileTransferError('目标父目录发生了重定向', [relative])\n  }\n}\n\nasync function boundedJson(file: string, limit: number): Promise<unknown> {\n  const stat = await lstat(file, { bigint: true })\n  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > BigInt(limit)) throw new FileTransferError('文件交接元数据不是有界的普通文件')\n  const handle = await open(file, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0))\n  try {\n    const opened = await handle.stat({ bigint: true })\n    if (opened.ino !== stat.ino || opened.dev !== stat.dev || opened.size > BigInt(limit)) throw new FileTransferError('文件交接元数据发生变化')\n    const buffer = Buffer.alloc(limit + 1)\n    let length = 0\n    while (length < buffer.length) {\n      const { bytesRead } = await handle.read(buffer, length, buffer.length - length, length)\n      if (!bytesRead) break\n      length += bytesRead\n    }\n    if (length > limit) throw new FileTransferError('文件交接元数据超过读取上限')\n    return JSON.parse(buffer.subarray(0, length).toString('utf8')) as unknown\n  } finally { await handle.close() }\n}\n\nasync function assertOwner(transfer: FileTransfer): Promise<void> {\n  const { repo, ref } = transfer.journal\n  validRef(ref)\n  const stat = await lstat(transfer.root)\n  if (!equalPath(transfer.root, path.join(repo, `.agent-compare-transfer-${ref.id}`))\n    || !stat.isDirectory() || stat.isSymbolicLink() || !equalPath(await realpath(transfer.root), transfer.root)\n    || !equalPath(await realpath(repo), repo)) throw new FileTransferError('文件交接目录的归属无法确认')\n  const owner = await boundedJson(path.join(transfer.root, 'owner.json'), 4096) as Record<string, unknown>\n  if (owner.schema !== 'agent-compare.file-transfer/v1' || owner.repo !== repo || owner.id !== ref.id || owner.token !== ref.token) throw new FileTransferError('文件交接目录的归属标记不匹配')\n  for (const directory of ['next', 'before', 'undo', 'checkout', 'restore']) {\n    const file = path.join(transfer.root, directory), child = await lstat(file)\n    if (!child.isDirectory() || child.isSymbolicLink() || !equalPath(await realpath(file), file)) throw new FileTransferError('文件交接子目录被替换或重定向')\n  }\n}\n\nasync function syncDirectory(directory: string): Promise<void> {\n  try {\n    const handle = await open(directory, 'r')\n    try { await handle.sync() } finally { await handle.close() }\n  } catch (error) {\n    if (process.platform !== 'win32' || !['EACCES', 'EPERM', 'EINVAL', 'EISDIR', 'EBADF'].includes((error as NodeJS.ErrnoException).code ?? '')) throw error\n  }\n}\n\n/** Restore through a fresh inode, retaining the captured original independently of future edits. */\nasync function restoreCopy(transfer: FileTransfer, source: string, target: string): Promise<void> {\n  await assertOwner(transfer)\n  const before = await fileFingerprint(source)\n  if (before.kind !== 'file') throw new FileTransferError('保留内容不是可自动恢复的普通文件')\n  const prepared = path.join(transfer.root, 'restore', randomBytes(16).toString('hex'))\n  await copyFile(source, prepared, constants.COPYFILE_EXCL)\n  if ((before.mode! & 0o200) === 0) await chmod(prepared, (before.mode! & 0o777) | 0o200)\n  const handle = await open(prepared, 'r+')\n  try { await handle.sync() } finally { await handle.close() }\n  if ((before.mode! & 0o200) === 0) await chmod(prepared, before.mode! & 0o777)\n  if (!sameFile(before, await fileFingerprint(source)) || !sameFile(before, await fileFingerprint(prepared), false)) throw new FileTransferError('复制保留内容时又出现了编辑，请重试恢复')\n  await link(prepared, target)\n  await syncDirectory(path.dirname(target))\n}\n\nasync function save(transfer: FileTransfer): Promise<void> {\n  await assertOwner(transfer)\n  const bytes = JSON.stringify(transfer.journal)\n  if (Buffer.byteLength(bytes) > JOURNAL_BYTES) throw new FileTransferError('文件交接记录过大，请另存分支')\n  const temporary = path.join(transfer.root, `.journal-${randomBytes(8).toString('hex')}`)\n  const handle = await open(temporary, 'wx', 0o600)\n  try { await handle.writeFile(bytes); await handle.sync() } finally { await handle.close() }\n  await rename(temporary, path.join(transfer.root, 'journal.json'))\n  await syncDirectory(transfer.root)\n}\n\nfunction validFingerprint(value: unknown): value is FileFingerprint {\n  if (!value || typeof value !== 'object') return false\n  const fp = value as FileFingerprint\n  return fp.kind === 'missing' || fp.kind === 'other' || (fp.kind === 'file' && /^[0-9a-f]{64}$/.test(fp.sha256 ?? '')\n    && Number.isSafeInteger(fp.size) && fp.size! >= 0 && fp.size! <= MAX_BYTES && Number.isSafeInteger(fp.mode)\n    && /^\\d+$/.test(fp.device ?? '') && /^\\d+$/.test(fp.inode ?? '') && /^-?\\d+$/.test(fp.modified ?? ''))\n}\n\nexport async function loadFileTransfer(repo: string, ref: FileTransferRef): Promise<FileTransfer> {\n  validRef(ref)\n  repo = await realpath(repo)\n  const root = path.join(repo, `.agent-compare-transfer-${ref.id}`)\n  const placeholder: FileTransfer = { root, journal: { schema: 'agent-compare.file-transfer/v1', repo, ref, state: 'prepared', entries: [] } }\n  await assertOwner(placeholder)\n  const journal = await boundedJson(path.join(root, 'journal.json'), JOURNAL_BYTES) as Journal\n  if (journal.schema !== 'agent-compare.file-transfer/v1' || journal.repo !== repo || journal.ref?.id !== ref.id || journal.ref?.token !== ref.token\n    || !['prepared', 'writing', 'applied', 'restoring', 'restored', 'recovery'].includes(journal.state)\n    || !Array.isArray(journal.entries) || journal.entries.length > MAX_ENTRIES) throw new FileTransferError('文件交接日志格式不支持')\n  const seen = new Set<string>()\n  for (const entry of journal.entries) {\n    validPath(entry.path)\n    if (seen.has(entry.path) || !validFingerprint(entry.before) || !validFingerprint(entry.after)\n      || !['prepared', 'capturing', 'captured', 'publishing', 'published', 'undoing', 'restored'].includes(entry.phase)) throw new FileTransferError('文件交接日志内容无效')\n    seen.add(entry.path)\n  }\n  return { root, journal }\n}\n\n/** Prepare all replacement bytes and prove no-replace links work before moving any project file. */\nexport async function prepareFileTransfer(repo: string, tree: string, operations: readonly { path: string; status: string }[], ref: FileTransferRef, expected?: Record<string, FileFingerprint>): Promise<FileTransfer> {\n  validRef(ref)\n  repo = await realpath(repo)\n  if (operations.length > MAX_ENTRIES) throw new FileTransferError('改动文件数量超过直接写回上限，请另存分支')\n  const paths = operations.map(operation => operation.path)\n  if (new Set(paths.map(file => process.platform === 'win32' ? file.toLowerCase() : file)).size !== paths.length) throw new FileTransferError('改动包含重复或大小写冲突的路径，请另存分支')\n  const before = expected ?? await transferPreimages(repo, paths)\n  for (const relative of paths) {\n    await ordinaryParents(repo, relative, false)\n    if (before[relative]?.kind === 'other') throw new FileTransferError('符号链接或特殊文件不能直接写回，请另存分支查看', [relative])\n  }\n  const modes = await git(repo, ['ls-tree', '-r', '-z', '--full-tree', tree])\n  const files = new Map(modes.split('\\0').filter(Boolean).map(line => [line.slice(line.indexOf('\\t') + 1), line.slice(0, 6)]))\n  for (const operation of operations) if (operation.status !== 'D' && !['100644', '100755'].includes(files.get(operation.path) ?? '')) throw new FileTransferError('这类文件变更需要另存分支查看', [operation.path])\n  const root = path.join(repo, `.agent-compare-transfer-${ref.id}`)\n  await mkdir(root, { mode: 0o700 })\n  await writeFile(path.join(root, '.gitignore'), '*\\n', { flag: 'wx', mode: 0o600 })\n  await writeFile(path.join(root, 'owner.json'), JSON.stringify({ schema: 'agent-compare.file-transfer/v1', repo, id: ref.id, token: ref.token }), { flag: 'wx', mode: 0o600 })\n  for (const directory of ['next', 'before', 'undo', 'checkout', 'restore']) await mkdir(path.join(root, directory))\n  const transfer: FileTransfer = { root, journal: { schema: 'agent-compare.file-transfer/v1', repo, ref, state: 'prepared', entries: [] } }\n  const probe = await open(path.join(root, 'link-probe'), 'wx', 0o600)\n  await probe.close()\n  try { await link(path.join(root, 'link-probe'), path.join(root, 'link-probe-copy')) } catch { throw new FileTransferError('当前文件系统不支持不覆盖已有路径的文件交接，请另存分支') }\n  const checkout = path.join(root, 'checkout')\n  const env = { GIT_INDEX_FILE: path.join(root, 'index'), GIT_WORK_TREE: checkout }\n  const limits = { timeoutMs: 60_000 }\n  await git(repo, ['read-tree', tree], env, undefined, limits)\n  const writes = operations.filter(operation => operation.status !== 'D').map(operation => operation.path)\n  const attributes = [...files.keys()].filter(file => path.posix.basename(file) === '.gitattributes')\n  if (attributes.length) await git(repo, ['checkout-index', '--force', '--stdin', '-z', `--prefix=${checkout.replace(/\\\\/g, '/')}/`], env, attributes.join('\\0') + '\\0', limits)\n  if (writes.length) await git(repo, ['checkout-index', '--force', '--stdin', '-z', `--prefix=${checkout.replace(/\\\\/g, '/')}/`], env, writes.join('\\0') + '\\0', limits)\n  let retainedBytes = 0\n  for (const [index, operation] of operations.entries()) {\n    const beforeFile = before[operation.path] ?? MISSING\n    let after = MISSING\n    if (operation.status !== 'D') {\n      await rename(path.join(checkout, operation.path), slot(transfer, 'next', index))\n      const handle = await open(slot(transfer, 'next', index), 'r+')\n      try { await handle.sync() } finally { await handle.close() }\n      after = await fileFingerprint(slot(transfer, 'next', index))\n      if (after.kind !== 'file') throw new FileTransferError('候选不是普通文件，请另存分支', [operation.path])\n    }\n    retainedBytes += (beforeFile.size ?? 0) + (after.size ?? 0)\n    if (retainedBytes > MAX_BYTES) throw new FileTransferError('本次文件交接超过原始内容保留上限，请另存分支')\n    transfer.journal.entries.push({ path: operation.path, before: beforeFile, after, phase: 'prepared' })\n  }\n  await save(transfer)\n  return transfer\n}\n\nexport function affectedTransferPaths(transfer: FileTransfer): string[] {\n  return transfer.journal.entries.filter(entry => entry.phase !== 'prepared').map(entry => entry.path)\n}\n\n/** Capture the actual old inode first; publish a hard link that can never replace an existing path. */\nexport async function publishTransferEntry(transfer: FileTransfer, index: number): Promise<void> {\n  await assertOwner(transfer)\n  const entry = transfer.journal.entries[index]!\n  if (entry.phase !== 'prepared' || await statIfPresent(slot(transfer, 'before', index))) throw new FileTransferError('这个文件交接不能重复执行', [entry.path])\n  const target = path.join(transfer.journal.repo, entry.path)\n  await ordinaryParents(transfer.journal.repo, entry.path, entry.after.kind !== 'missing')\n  transfer.journal.state = 'writing'\n  if (entry.before.kind !== 'missing') {\n    entry.phase = 'capturing'; await save(transfer)\n    await rename(target, slot(transfer, 'before', index))\n    await syncDirectory(path.dirname(target)); await syncDirectory(path.join(transfer.root, 'before'))\n    entry.phase = 'captured'; await save(transfer)\n    if (!sameFile(await fileFingerprint(slot(transfer, 'before', index)), entry.before)) throw new FileTransferError('文件交接时检测到新编辑，已保留实际原始文件', [entry.path])\n  }\n  entry.phase = 'publishing'; await save(transfer)\n  if (entry.after.kind !== 'missing') {\n    if (!sameFile(await fileFingerprint(slot(transfer, 'next', index)), entry.after)) throw new FileTransferError('准备好的候选文件发生变化', [entry.path])\n    await link(slot(transfer, 'next', index), target)\n    await syncDirectory(path.dirname(target))\n  }\n  entry.phase = 'published'; await save(transfer)\n}\n\nexport async function finishFileTransfer(transfer: FileTransfer): Promise<void> {\n  for (const [index, entry] of transfer.journal.entries.entries()) {\n    if (entry.before.kind !== 'missing' && !sameFile(await fileFingerprint(slot(transfer, 'before', index)), entry.before)) throw new FileTransferError('交接期间保留的原始文件又发生了变化', [entry.path])\n  }\n  transfer.journal.state = 'applied'\n  await save(transfer)\n}\n\n/** Never delete or replace a path created or edited by another writer. All captured bytes remain retained. */\nexport async function restoreFileTransfer(repo: string, ref: FileTransferRef): Promise<{ restored: string[]; conflicts: string[] }> {\n  const transfer = await loadFileTransfer(repo, ref)\n  transfer.journal.state = 'restoring'; await save(transfer)\n  const restored: string[] = [], conflicts: string[] = []\n  for (let index = transfer.journal.entries.length - 1; index >= 0; index--) {\n    const entry = transfer.journal.entries[index]!, target = path.join(transfer.journal.repo, entry.path)\n    try {\n      await assertOwner(transfer)\n      await ordinaryParents(transfer.journal.repo, entry.path, false)\n      const backup = slot(transfer, 'before', index), removed = slot(transfer, 'undo', index)\n      const backupStat = await statIfPresent(backup), removedStat = await statIfPresent(removed)\n      let current = await fileFingerprint(target)\n      if (removedStat && !sameFile(await fileFingerprint(removed), entry.after, false)) {\n        if (current.kind === 'missing' && removedStat.isFile() && !removedStat.isSymbolicLink()) await restoreCopy(transfer, removed, target)\n        throw new FileTransferError('撤销交接时出现了新编辑，已保留', [entry.path])\n      }\n      if (backupStat && current.kind === 'missing') {\n        if (!backupStat.isFile() || backupStat.isSymbolicLink()) throw new FileTransferError('保留内容需要手动恢复', [entry.path])\n        await restoreCopy(transfer, backup, target)\n        entry.phase = 'restored'; await save(transfer); restored.push(entry.path); continue\n      }\n      const original = backupStat ? await fileFingerprint(backup) : entry.before\n      if (backupStat && sameFile(current, original, false)) { entry.phase = 'restored'; await save(transfer); restored.push(entry.path); continue }\n      if (entry.phase === 'prepared' || (entry.phase === 'capturing' &&